sudo -H sh -c 'set -u; . /root/infraset-client.env; d=/tmp/infraset-evaluator-p1; u=$(jq -r .data.username "$d/a.json"); p=$(jq -r .data.password "$d/a.json"); env PGUSER="$u" PGPASSWORD=[REDACTED] PGCONNECT_TIMEOUT=5 psql -XAt -v ON_ERROR_STOP=1 >"$d/a-test.out" 2>"$d/a-test.err" <<SQL
\conninfo
SELECT 'identity|' || current_user || '|' || current_database();
SELECT 'table_present|' || (to_regclass('public.credential_probe') IS NOT NULL);
SELECT 'role_flags|' || rolsuper || '|' || rolcreatedb || '|' || rolcreaterole || '|' || rolreplication || '|' || rolbypassrls FROM pg_roles WHERE rolname=current_user;
SELECT 'table_privs|' || has_table_privilege(current_user,'public.credential_probe','SELECT') || '|' || has_table_privilege(current_user,'public.credential_probe','INSERT') || '|' || has_table_privilege(current_user,'public.credential_probe','UPDATE') || '|' || has_table_privilege(current_user,'public.credential_probe','DELETE');
SELECT 'schema_create|' || has_schema_privilege(current_user,'public','CREATE');
SELECT 'database_create|' || has_database_privilege(current_user,current_database(),'CREATE');
BEGIN;
INSERT INTO public.credential_probe (payload) VALUES ('infraset-evaluator-p1-a') RETURNING id AS probe_id \gset
SELECT 'insert_ok|' || probe_id;
SELECT 'select_ok|' || count(*) FROM public.credential_probe WHERE id=probe_id;
UPDATE public.credential_probe SET payload='infraset-evaluator-p1-a-updated' WHERE id=probe_id RETURNING id AS probe_id \gset
SELECT 'update_ok|' || probe_id;
DELETE FROM public.credential_probe WHERE id=probe_id RETURNING id;
SELECT 'delete_ok';
COMMIT;
SQL
s=$?; printf "credential_a_psql_exit=%s\n" "$s"; grep -q "SSL connection" "$d/a-test.out" && printf "credential_a_tls_conninfo=ssl\n" || printf "credential_a_tls_conninfo=missing\n"; for m in identity table_present role_flags table_privs schema_create database_create insert_ok select_ok update_ok delete_ok; do grep -q "^$m|" "$d/a-test.out" && printf "credential_a_%s=present\n" "$m" || printf "credential_a_%s=missing\n" "$m"; done; env PGUSER="$u" PGPASSWORD=[REDACTED] PGCONNECT_TIMEOUT=5 psql -XAt -v ON_ERROR_STOP=1 -c "BEGIN; CREATE TABLE public.infraset_evaluator_forbidden_p1_a(x integer); ROLLBACK;" >"$d/a-create.out" 2>"$d/a-create.err"; cs=$?; printf "credential_a_forbidden_create_exit=%s\n" "$cs"; env PGUSER="$u" PGPASSWORD=[REDACTED] PGCONNECT_TIMEOUT=5 psql -XAt -v ON_ERROR_STOP=1 -c "SELECT count(*) FROM pg_authid" >"$d/a-authid.out" 2>"$d/a-authid.err"; as=$?; printf "credential_a_pg_authid_exit=%s\n" "$as"; grep -qi "permission denied" "$d/a-create.err" && printf "credential_a_forbidden_create_denied=yes\n" || true; grep -qi "permission denied" "$d/a-authid.err" && printf "credential_a_pg_authid_denied=yes\n" || true'

